import unittest

import collide
import engine
import physics
import world
from units import (BIRD_H, BIRD_W, BIRD_X, FIELD_H, FLAP_V, G, GAP_H, GLIDE_VY,
                   PIPE_W, SPAWN_EVERY, SPAWN_X, VY_MAX)


class PhysicsTests(unittest.TestCase):
    def test_flap_sets_vy_instead_of_adding(self):
        self.assertEqual(physics.step_bird(560, 200, True), (533, FLAP_V, True))

    def test_gravity_clamps_at_vy_max(self):
        self.assertEqual(physics.step_bird(0, VY_MAX - 1, False), (VY_MAX, VY_MAX, True))
        self.assertEqual(physics.step_bird(0, 100, False), (100 + G, 100 + G, True))

    def test_ceiling_is_soft_and_zeroes_vy(self):
        self.assertEqual(physics.step_bird(10, -27, True), (0, 0, True))

    def test_floor_clamps_y_and_kills_without_zeroing_vy(self):
        y, vy, alive = physics.step_bird(FIELD_H - BIRD_H - 18, VY_MAX, False)
        self.assertEqual((y, alive), (FIELD_H - BIRD_H, False))
        self.assertEqual(vy, VY_MAX)

    def test_floor_boundary_exact_is_alive(self):
        y, vy, alive = physics.step_bird(FIELD_H - BIRD_H - 18, 18, False)
        self.assertEqual((y, vy, alive), (FIELD_H - BIRD_H, 18, True))


class WorldTests(unittest.TestCase):
    def test_lcg_values(self):
        self.assertEqual(world.lcg(0), 12345)
        self.assertEqual(world.lcg(1), 1103527590)
        for s in (7, 123456789, 2147483647):
            self.assertLess(world.lcg(s), 2147483648)

    def test_spawn_advances_lcg_once_and_uses_advanced_state(self):
        pipe, s2 = world.spawn(0, 7)
        self.assertEqual(s2, world.lcg(7))
        self.assertEqual(pipe["gap_top"], 40 + (s2 >> 8) % 80)
        self.assertEqual(pipe["x"], SPAWN_X)
        self.assertFalse(pipe["passed"])

    def test_spawn_only_on_spawn_ticks(self):
        for t in range(SPAWN_EVERY * 2):
            pipe, s = world.spawn(t, 7)
            if t % SPAWN_EVERY == 0:
                self.assertIsNotNone(pipe)
                self.assertEqual(s, world.lcg(7))
            else:
                self.assertIsNone(pipe)
                self.assertEqual(s, 7)

    def test_cull_boundary(self):
        kept = {"x": -PIPE_W + 1, "gap_top": 0, "passed": False}
        dropped = {"x": -PIPE_W, "gap_top": 0, "passed": False}
        self.assertEqual(world.cull([dropped, kept]), [kept])


class CollideTests(unittest.TestCase):
    def test_rect_overlap_half_open_edges(self):
        self.assertFalse(collide.rect_overlap(0, 10, 10, 20))
        self.assertFalse(collide.rect_overlap(0, 10, -5, 0))
        self.assertTrue(collide.rect_overlap(0, 10, 9, 20))
        self.assertTrue(collide.rect_overlap(0, 10, 0, 10))

    def test_pipe_right_edge_at_bird_x_does_not_hit(self):
        pipe = {"x": BIRD_X - PIPE_W, "gap_top": 40}
        self.assertFalse(collide.pipe_hit(0, pipe))

    def test_bird_exactly_inside_gap_survives(self):
        pipe = {"x": BIRD_X, "gap_top": 100}
        self.assertFalse(collide.pipe_hit(100, pipe))
        self.assertFalse(collide.pipe_hit(100 + GAP_H - BIRD_H, pipe))

    def test_bird_just_outside_gap_hits(self):
        pipe = {"x": BIRD_X, "gap_top": 100}
        self.assertTrue(collide.pipe_hit(99, pipe))
        self.assertTrue(collide.pipe_hit(100 + GAP_H - BIRD_H + 1, pipe))


class GlideBonusTests(unittest.TestCase):
    def test_bonus_awarded_when_level(self):
        st = engine.run(7, 200, "0010")
        self.assertEqual(st["score"], 8)

    def test_no_bonus_when_diving(self):
        # Flap 36 ticks to stick to the ceiling, then free-fall: pipe 0 is
        # passed at t=45 with vy=180 > GLIDE_VY, so it is worth exactly 1.
        st = engine.run(7, 60, "1" * 36 + "0" * 24)
        self.assertEqual(st["score"], 1)
        self.assertFalse(st["alive"])
        self.assertEqual(st["ticks_run"], 47)


class TickOrderTests(unittest.TestCase):
    def test_fatal_tick_scores_nothing(self):
        # Flap 35 ticks to the ceiling, then free-fall: the floor kill lands on
        # t=45, exactly pipe 0's pass tick. Scoring runs after collision and a
        # dead bird scores nothing, so the score stays 0 (an engine that scored
        # anyway would report 1, since vy=198 > GLIDE_VY).
        st = engine.run(7, 60, "1" * 35 + "0" * 25)
        self.assertEqual(st["score"], 0)
        self.assertFalse(st["alive"])
        self.assertEqual(st["ticks_run"], 46)

    def test_spawn_and_scroll_happen_on_their_own_tick(self):
        # Flap every tick: the bird sticks to the ceiling at y=0, outside any
        # gap. Pipe 0 (spawned at t=0) first overlaps the bird after the scroll
        # of t=40 (x=360), so the run must halt with ticks_run=41. If spawning
        # or scrolling lagged a tick, death would come at t=41 (ticks_run=42).
        st = engine.run(7, 60, "1" * 60)
        self.assertFalse(st["alive"])
        self.assertEqual(st["score"], 0)
        self.assertEqual(st["ticks_run"], 41)

    def test_state_keys_without_powerups(self):
        st = engine.run(7, 200, "0010")
        self.assertEqual(set(st), {"y", "vy", "score", "alive", "ticks_run"})


if __name__ == "__main__":
    unittest.main()

